create or replace function public.create_feedback_ticket(target_category text,target_title text,target_body text,target_context jsonb default '{}'::jsonb) returns bigint language plpgsql security definer set search_path=public as $$ declare caller uuid := auth.uid(); new_id bigint; begin if caller is null then raise exception 'authentication required'; end if; if not exists(select 1 from public.account_status a where a.user_id=caller and a.status='ACTIVE') then raise exception 'active account required'; end if; if target_category not in ('CONTENT_ERROR','BUG','SUGGESTION','OTHER') then raise exception 'invalid category'; end if; if char_length(trim(coalesce(target_title,''))) not between 1 and 120 then raise exception 'invalid title'; end if; if char_length(trim(coalesce(target_body,''))) not between 1 and 4000 then raise exception 'invalid body'; end if; insert into public.feedback_tickets(user_id,category,title,context) values(caller,target_category,trim(target_title),coalesce(target_context,'{}'::jsonb)) returning id into new_id; insert into public.feedback_messages(ticket_id,sender_id,body) values(new_id,caller,trim(target_body)); return new_id; end $$; revoke all on function public.create_feedback_ticket(text,text,text,jsonb) from public,anon; grant execute on function public.create_feedback_ticket(text,text,text,jsonb) to authenticated;